{"cmd":"python - <<'PY'
import numpy as np, glob, datetime as dt

def parse(s):
    return dt.datetime.fromisoformat(str(s))

vals=[]
for p in glob.glob('/root/data/*.npz'):
    z=np.load(p, allow_pickle=True)
    t0=parse(z['start_time'])
    te=parse(z['event_time'])
    vals.append((te - t0).total_seconds())
print('min', min(vals), 'max', max(vals), 'mean', sum(vals)/len(vals))
PY"}

